    bestTimeToEat: [ ],
    goodPairings: [ ],
    avoidPairings: [ ],
    cautionGroups: [ ],
    cautions: "",
    koreanCautions: "",
    benefits: "灵芝又称灵芝草、神芝、芝草、仙草、瑞草，是多孔菌科植物赤芝或紫芝的全株。以紫灵芝药效为最好，灵芝原产于亚洲东部，中国分布最广的在江西，灵芝作为拥有数千年药用历史的中国传统珍贵药材，具备很高的药用价值，经过科研机构数十年的现代药理学研究证实，灵芝对于增强人体免疫力，调节血糖，控制血压，辅助肿瘤放化疗，保肝护肝，促进睡眠等方面均具有显著疗效。 含水分、蛋白质、粗纤维、灰分、胡萝卜素、维生素B，、维生素B：、维生素c、烟酸、维生素E、钾、钠、钙、镁、铁、锰、锌、铜、磷、硒、肌红蛋白、p一胡萝卜素、海胆烯酮、鸡油菌黄质、磷质、甾醇以及葡萄糖甙、香树脂醇类等。芝含有麦角固醇、有机酸、氨基酸、葡萄糖、多糖类、树脂、甘露醇、生物碱、内酯、香豆精、水溶性蛋白质和多种酶类。补肝气益心气镇静镇痛强心降压降血脂降血糖",
    allergens: [ ],
    ingredients: [
        "灵芝"
    ],
