    _id: ObjectId("69fb44f54482728ac644cea6"),
    name: "Vegetable ingredients 11e31c",
    koreanName: "Vegetable ingredients 11e31c",
    chineseName: "牛肚菌",
    dataType: "food-material-master",
    category: "vegetable",
    foodGroup: "plant food",
    foodSubgroup: "菌类",
    servingSize: "100 g edible portion",
    calories: Int32("0"),
    macros: {
        protein: Int32("0"),
        fat: Int32("0"),
        carbs: Int32("0"),
        fiber: Int32("0")
    },
    saturatedFat: Int32("0"),
